&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;L&#233;chi lotus&lt;div style=&quot;float:right;&quot;&gt;FP 5&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Plante&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Plante.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Aquatique&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Aquatique.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Tropical&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Tropical.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 5 p.167&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 1 600
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Plante.html&quot; title=&quot;Plante&quot;&gt;Plante&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-L&#233;chi.html&quot; title=&quot;L&#233;chi (sous-type)&quot;&gt;l&#233;chi&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-M&#233;tamorphe.html&quot; title=&quot;M&#233;tamorphe (sous-type)&quot;&gt;m&#233;tamorphe&lt;/a&gt;) de taille P, N
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +6 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +14
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Aura&lt;/b&gt; tranquillit&#233; (6 m, DD 15, 10 rounds)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 20, contact 18, pris au d&#233;pourvu 17 (Dex +2, esquive +1, naturelle +2, Sag +4, taille +1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 52 (7d8+21)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +4, &lt;b&gt;Vig&lt;/b&gt; +8, &lt;b&gt;Vol&lt;/b&gt; +6
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Immunit&#233;s&lt;/b&gt; &#233;lectricit&#233;, son, &lt;a class=&quot;pagelink&quot; href=&quot;Traits-Des-Plantes-(Capacit&#233;).html&quot; title=&quot;Traits des plantes (Ext)&quot;&gt;traits des plantes&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m ; sentier de n&#233;nuphars
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; coup, +8 (1d4)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; projection de graines, +8 (1d3 non-l&#233;taux/&#215;3 plus pollen onirique)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; pollen onirique, projection de graines
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 14 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +16)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
Constant — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sentier-De-N&#233;nuphars.html&quot; title=&quot;Sentier de n&#233;nuphars&quot;&gt;sentier de n&#233;nuphars&lt;/a&gt;&lt;/i&gt;, passage sans trace
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 10, &lt;b&gt;Dex&lt;/b&gt; 15, &lt;b&gt;Con&lt;/b&gt; 16, &lt;b&gt;Int&lt;/b&gt; 16, &lt;b&gt;Sag&lt;/b&gt; 19, &lt;b&gt;Cha&lt;/b&gt; 15
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +5 ; &lt;b&gt;BMO&lt;/b&gt; +4 ; &lt;b&gt;DMD&lt;/b&gt; 21
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l&#39;initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Connaissances [religion])
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) +13, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +6 (+10 en milieu aquatique), &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +0 (+4 en milieu aquatique) ; &lt;b&gt;Modificateurs raciaux&lt;/b&gt; +4 en Discr&#233;tion en milieu aquatique, +4 en Survie en milieu aquatique
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; druidique, sylvestre ; langue des plantes (arbre-lotus)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Forme-(Capacit&#233;).html&quot; title=&quot;Changement de forme (Sur)&quot;&gt;changement de forme&lt;/a&gt; (petite fleur de arbre-lotus ; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Darbre.html&quot; title=&quot;Forme d&amp;#39;arbre&quot;&gt;forme d&#39;arbre&lt;/a&gt;&lt;/i&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-L&#233;chi.html&quot; title=&quot;L&#233;chi (sous-type)&quot;&gt;explosion verdoyante&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; lacs ou &#233;tangs, chauds
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation&lt;/b&gt; solitaire
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Aura de tranquillit&#233; (Sur).&lt;/b&gt; Une aura de calme se d&#233;gage des l&#233;chis lotus sur un rayon de 6 m&#232;tres. Cette aura fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Apaisement-Des-&#201;motions.html&quot; title=&quot;Apaisement des &#233;motions&quot;&gt;apaisement des &#233;motions&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Vol&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 annule). Une cr&#233;ature qui r&#233;ussit son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; est immunis&#233;e &#224; l’aura de ce l&#233;chi pendant 24 heures. Le DD du jet de sauvegarde est bas&#233; sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pollen onirique (Ext).&lt;/b&gt; Un l&#233;chi lotus peut expulser du pollen sur un c&#244;ne de 4,5 m&#232;tres. Toutes les cr&#233;atures qui se trouvent dans ce c&#244;ne (ainsi que celles qui ont subi des d&#233;g&#226;ts caus&#233;s par la projection de graines) doivent r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 16 ou s’endormir pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Le DD du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; est bas&#233; sur la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Projection de graines (Ext).&lt;/b&gt; Un l&#233;chi lotus peut tirer plusieurs graines sur des cibles qui se trouvent dans un rayon de 9 m&#232;tres de lui. Il peut tirer 6 graines comme action simple et distribuer ces graines comme il le veut entre les cibles qui se trouvent &#224; sa port&#233;e. Chaque graine inflige 1d3 points de d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non l&#233;taux&lt;/a&gt;. Le l&#233;chi fait un unique &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; pour d&#233;terminer la pr&#233;cision de toutes les graines qu’il projette. L’attaque a un multiplicateur critique de x3 et le l&#233;chi ne fait qu’un seul jet pour confirmer une menace critique.
&lt;/div&gt;
&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;L&#233;chi.html&quot; title=&quot;Les l&#233;chis&quot;&gt;l&#233;chis&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Cette plante dont le corps ressemble &#224; une fleur de arbre-lotus d&#233;gage une aura de s&#233;r&#233;nit&#233;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les &#233;nigmatiques l&#233;chis lotus sont les sages gardiens des &#233;tangs et des lacs isol&#233;s. Ils passent le plus clair de leur temps &#224; m&#233;diter sous la forme de fleurs de lotus, parfois pendant des d&#233;cennies sans interruption. Bien que les l&#233;chis lotus passent la plupart de leur temps isol&#233;s &#224; flotter et &#224; r&#233;fl&#233;chir, ce n’est pas pour &#233;viter la compagnie d’autres cr&#233;atures et ils prennent une forme humano&#239;de d&#232;s qu’ils veulent parler. Ils trouvent les discussions autour de la religion et de la philosophie particuli&#232;rement fascinantes et se r&#233;jouissent de d&#233;couvrir de nouveaux points de vue. Bien qu’ils &#233;tudient de mani&#232;re approfondie les d&#233;it&#233;s qui se font les chantres du perfectionnement de soi et de la contemplation, ils ne r&#233;v&#232;rent pas pour autant de tels &#234;tres.&lt;br /&gt;&lt;br /&gt;Les l&#233;chis lotus n’ont pas pour habitude de r&#233;pondre directement aux questions. Ils soutiennent que la contemplation et la discussion sont bien plus enrichissantes que les r&#233;ponses concr&#232;tes dont l’utilit&#233; est limit&#233;e &#224; la question qui vient d’&#234;tre pos&#233;e. Qui plus est, ils sont convaincus que ceux qui re&#231;oivent des r&#233;ponses directes ont plus de risques d’accepter aveugl&#233;ment ce qu’on leur dit plut&#244;t que de r&#233;fl&#233;chir par eux-m&#234;mes. Confront&#233;s &#224; l’impatience, les l&#233;chis lotus coupent court &#224; la discussion en reprenant leur forme de lotus. Ils &#233;vitent le combat autant que possible, pr&#233;f&#233;rant calmer les temp&#233;raments &#233;chauff&#233;s gr&#226;ce &#224; leurs auras de tranquillit&#233;, ou faire sombrer les cr&#233;atures violentes dans le sommeil gr&#226;ce &#224; leur pollen soporifique.&lt;br /&gt;&lt;br /&gt;Un l&#233;chi lotus typique mesure 90 centim&#232;tres et p&#232;se 7,5 kilos.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Faire pousser un l&#233;chi lotus&lt;a class=&quot;headeranchor&quot; id=&quot;Faire_pousser_un_l&#233;chi_lotus_0&quot; href=&quot;#Faire_pousser_un_l&#233;chi_lotus_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Le meilleur endroit pour faire pousser un l&#233;chi lotus est un &#233;tang ou lac chaud qui se trouve dans une r&#233;gion calme. L’individu qui veut faire pousser ce l&#233;chi doit planter une graine de lotus au bord de l’eau, s’asseoir &#224; c&#244;t&#233; de celle-ci et m&#233;diter jusqu’&#224; ce qu’elle germe.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;NLS&lt;/b&gt; 12 ; &lt;b&gt;Prix&lt;/b&gt; 9 000 po  
&lt;b&gt;Conditions requises&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) 5 rangs, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) 5 rangs, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-Naturels-V.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s naturels V&quot;&gt;convocation d’alli&#233;s naturels V&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croissance-V&#233;g&#233;tale.html&quot; title=&quot;Croissance v&#233;g&#233;tale&quot;&gt;croissance v&#233;g&#233;tale&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sentier-De-N&#233;nuphars.html&quot; title=&quot;Sentier de n&#233;nuphars&quot;&gt;sentier de n&#233;nuphars&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature ou religion) &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 19 ; &lt;b&gt;Co&#251;t&lt;/b&gt; 4 500 po
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
